    { name: 'John', age: 20 },
    { name: 'Alice', age: 18 }
  ]
}

### Response:
import React from 'react';

class Table extends React.Component {
  render() {
    const state = this.props.state;
    const dataRows = state.data.map(rowData => (
      <tr>
        <td>{rowData.name}</td>
        <td>{rowData.age}</td>
      </tr>
