### Instruction:
Compare two JSON objects in Python.

### Input:
first_obj = {
    'name': 'John',
    'age': 30
}
second_obj = {
    'name': 'John',
    'age': 34
}

### Response:
import json

# Compare two JSON objects and return `True` if equal, `False` if not
def compare_json_objects(first_obj, second_obj):
    first_obj_str = json.dumps(first_obj)
    second_obj_str = json.dumps(second_obj)
    if first_obj_str == second_obj_str:
        return True
    else:
        return False

if __name__ == '__main__':
    first_obj = {
        'name': 'John',
        'age': 30
    }
    second_obj = {
        'name': 'John',
        'age': 34
    }
    print(compare_json_objects(first_obj, second_obj))

