Find the cost of the cheapest product from a list of products in JSON format
"""

import json

def find_cheapest_product(products):
    cheapest_product = (None, float('inf'))
    for product in products:
        if product['Price'] < cheapest_product[1]:
            cheapest_product = (product['Name'], product['Price'])

    return cheapest_product[1]

if __name__ == '__main__':
    products = [
