import sys

from benchmark_base import BenchmarkBase

import torch


class Benchmark(BenchmarkBase):
    N = 200

    def __init__(self, use_loop=False):
        self.use_loop = use_loop
        super().__init__(
            category="symint_sum",
            backend="inductor",
            device="cpu",
        )

    def name(self):
        if self.use_loop:
            return f"{self.category()}_loop"

        return self.category()

    def description(self):
        return "see https://docs.google.com/document/d/11xJXl1etSmefUxPiVyk885e0Dl-4o7QwxYcPiMIo2iY/edit"

    def _prepare_once(self):
        torch._dynamo.config.capture_scalar_outputs = True
        torch.manual_seed(0)

        self.splits = torch.randint(10, (self.N,))

    def _prepare(self):
        torch._dynamo.reset()

    def _work(self):
        @torch.compile(fullgraph=True)
        def f(a):
            xs = a.tolist()
            y = 0
            if self.use_loop:
                for i in xs:
                    y += i
            else:
                y = sum(xs)
            return torch.tensor(y)

        f(self.splits)


def main():
    result_path = sys.argv[1]
    Benchmark(
        use_loop=False
    ).enable_compile_time_instruction_count().collect_all().append_results(result_path)
    Benchmark(
        use_loop=True
    ).enable_compile_time_instruction_count().collect_all().append_results(result_path)


if __name__ == "__main__":
    main()

import sys

from benchmark_base import BenchmarkBase

import torch


class Benchmark(BenchmarkBase):
    N = 20

    def __init__(self):
        super().__init__(
            category="update_hint",
            backend="inductor",
            device="cpu",
        )

    def name(self):
        return f"{self.category()}_regression"

    def description(self):
        return "information at https://github.com/pytorch/pytorch/pull/129893"

    def _prepare_once(self):
        torch._dynamo.config.capture_scalar_outputs = True
        torch.manual_seed(0)

        self.splits = torch.randint(10, (self.N,))
        sz = self.splits.sum().item()
        self.input = torch.randn(sz)

    def _prepare(self):
        torch._dynamo.reset()

    def _work(self):
        @torch.compile(fullgraph=True)
        def f(a, b):
            xs = b.tolist()
            for x in xs:
                torch._check(x >= 0)
                torch._check(x <= self.N)
            return a.split(xs)

        f(self.input, self.splits)


def main():
    result_path = sys.argv[1]
    Benchmark().enable_compile_time_instruction_count().collect_all().append_results(
        result_path
    )


