        self.inputs = {
            "input": input,
            "offset": torch.cat(
                (offsets, torch.tensor([input.size(0)], dtype=torch.long)), 0
            ),
        }
        self.set_module_name("embeddingbag")

    def forward(self, input, offset):
        return self.embedding(input, offset)


