			b.stmt(
				b.call(
					'$.async',
					context.state.node,
					node.metadata.expression.blockers(),
					b.array([b.thunk(expression, node.metadata.expression.has_await)]),
					b.arrow([context.state.node, b.id('$$html')], b.block([statement]))
