export function SvelteHead(node, context) {
	const block = /** @type {BlockStatement} */ (context.visit(node.fragment));

	context.state.template.push(
		b.stmt(
			b.call(
				'$.head',
				b.literal(hash(filename)),
				b.id('$$renderer'),
				b.arrow([b.id('$$renderer')], block)
			)
		)
