    beforeEach(async () => {
      testingModule = await Test.createTestingModule({
        imports: [OverwrittenModule],
      })
        .overrideModule(OverwrittenModule)
        .useModule(OverrideModule)
        .compile();
    });

    it('should override global modules using testing module builder', () => {
